local({
  items <- c("PEDSQLEF_A_212Y", "PEDSQLEF_B_212Y", "PEDSQLEF_C_212Y", "PEDSQLEF_D_212Y", "PEDSQLEF_E_212Y")
  x <- sapply(items, function(v) 100 - 25 * as.numeric(tbl[[v]]))
  n <- rowSums(!is.na(x))
  if_else(as.numeric(AGESVY) >= 2 & n >= length(items) / 2, rowMeans(x, na.rm = TRUE), NA_real_)
})

